function asNumber(value:number|string|null|undefined){const n=Number(value??0);return Number.isFinite(n)?n:0;}
function currency(value:number){return new Intl.NumberFormat("en-AU",{style:"currency",currency:"AUD",minimumFractionDigits:2}).format(value);}
function shortDate(value?:string|null){if(!value)return"—";const d=/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(`${value}T00:00:00Z`):new Date(value);if(Number.isNaN(d.getTime()))return"—";return new Intl.DateTimeFormat("en-AU",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).format(d);}
function statusLabel(status:FinancialStatus){return{draft:"Draft",submitted:"Pending Approval",changes_required:"Changes Required",rejected:"Rejected",approved:"Approved",paid:"Paid"}[status];}
function statusClass(status:FinancialStatus){switch(status){case"submitted":return"border-amber-200 bg-amber-50 text-amber-700";case"changes_required":return"border-orange-200 bg-orange-50 text-orange-700";case"rejected":return"border-rose-200 bg-rose-50 text-rose-700";case"approved":return"border-emerald-200 bg-emerald-50 text-emerald-700";case"paid":return"border-blue-200 bg-blue-50 text-blue-700";default:return"border-slate-200 bg-slate-50 text-slate-600";}}
function dueInfo(dueDate?:string|null,status?:FinancialStatus){if(!dueDate||status==="paid")return{label:status==="paid"?"Paid":"No due date",className:"bg-slate-100 text-slate-600"};const due=new Date(`${dueDate}T00:00:00`),today=new Date();today.setHours(0,0,0,0);const days=Math.round((due.getTime()-today.getTime())/86400000);if(days<0)return{label:`Overdue ${Math.abs(days)}d`,className:"bg-rose-100 text-rose-800"};if(days===0)return{label:"Due today",className:"bg-rose-100 text-rose-800"};if(days<=3)return{label:`Due in ${days}d`,className:"bg-orange-100 text-orange-800"};if(days<=7)return{label:`Due in ${days}d`,className:"bg-amber-100 text-amber-800"};return{label:`Due ${shortDate(dueDate)}`,className:"bg-slate-100 text-slate-600"};}
function addDays(value:string,days:number){if(!value)return"";const d=new Date(`${value}T00:00:00`);if(Number.isNaN(d.getTime()))return"";d.setDate(d.getDate()+days);return d.toISOString().slice(0,10);}
function vehicleLabel(a:VehicleAsset){return[a.vehicle_id,a.vehicle_rego,[a.make,a.model].filter(Boolean).join(" ")].filter(Boolean).join(" · ")||"Vehicle";}
