 const filteredInvoices=useMemo(()=>{const q=search.trim().toLowerCase();return invoices.filter(i=>{if(statusFilter!=="all"&&i.status!==statusFilter)return false;const due=dueInfo(i.due_date,i.status).label.toLowerCase();if(dueFilter==="overdue"&&!due.startsWith("overdue"))return false;if(dueFilter==="due_7"&&!(due.startsWith("due in")||due==="due today"))return false;if(dueFilter==="unpaid"&&i.status!=="approved")return false;if(!q)return true;return[i.submission_number,i.supplier_name,i.invoice_number,i.purchase_order_number,i.description].some(v=>String(v??"").toLowerCase().includes(q))})},[dueFilter,invoices,search,statusFilter]);
